import re, os
root='../../src'
names=set()
for dirp,_,files in os.walk(root):
    for f in files:
        if not f.endswith('.rs'): continue
        p=os.path.join(dirp,f); cut=None
        for i,l in enumerate(open(p),1):
            if '#[cfg(test)]' in l: cut=i; break
        for i,l in enumerate(open(p),1):
            if cut and i>=cut: break
            for m in re.finditer(r'var(?:_os)?\(\s*"(LENS_[A-Z0-9_]+)"', l): names.add(m.group(1))
print('distinct LENS_* env names read (non-test):', len(names))
print('\n'.join(sorted(names)))
